#[inductive(advance_tail_start)]
fn advance_tail_start_inductive(pre: Self, post: Self, node_id: NodeId)
    requires
        pre.combiner_valid(node_id, CombinerState::Idle),
        post.combiner[node_id] == CombinerState::AdvancingTail { observed_head: pre.head },
        forall |n: NodeId| 0 <= n < pre.num_replicas ==> pre.local_versions.contains_key(n),
        pre.pointer_ordering(),
    ensures
        post.combiner_valid(node_id, CombinerState::AdvancingTail { observed_head: pre.head }),
        post.all_combiner_valid(),
{
    // From pointer_ordering invariant in pre state:
    // forall |i| pre.local_versions.contains_key(i) ==> pre.head <= pre.local_versions[i]
    // And local_versions is not modified by the transition
    // So for all n: 0 <= n < num_replicas ==> pre.head <= post.local_versions[n]

    // Show the combiner_valid for AdvancingTail
    let observed_head = pre.head;
    assert forall |n| 0 <= n < post.num_replicas as nat implies observed_head <= post.local_versions[n] by {
        // From pre invariant pointer_ordering
        assert(pre.local_versions.contains_key(n as NodeId));
        assert(pre.head <= pre.local_versions[n as NodeId]);
        // local_versions is not modified
        assert(pre.local_versions[n as NodeId] == post.local_versions[n as NodeId]);
        assert(observed_head <= post.local_versions[n as NodeId]);
    }

    // Show all_combiner_valid
    assert forall |node_id2| #[trigger] post.combiner.contains_key(node_id2) implies
        post.combiner_valid(node_id2, post.combiner[node_id2]) by {
        if node_id2 == node_id {
            // We already showed this above
            assert(post.combiner_valid(node_id2, post.combiner[node_id2]));
        } else {
            // For other node_ids, combiner state is unchanged
            assert(post.combiner[node_id2] == pre.combiner[node_id2]);
            assert(pre.combiner_valid(node_id2, pre.combiner[node_id2]));
        }
    }
}

